"""Phoenix boss art (your new phoenix set). All frames face left.
fly: wing-beat loop.  cast: flares white-hot and hurls fireballs.  charge: winds up and streaks forward in flame (its dive).
wrap: wraps itself in fire, then spreads its wings (the crescent slash).  burst: engulfed in flame, it bursts into a ring of fire feathers.
death: explodes into embers and ash, then (frames 30-40) is reborn out of the smoke."""
import base64
import zlib
import pygame

W, H = 96, 94
AX, AY = 48, 47                   # body centre inside a frame
BEAK = (-21, -11)                         # beak offset from the body centre (1x)
ANIMS = {'fly': (21, ''), 'cast': (17, ''), 'charge': (17, ''), 'burst': (41, ''), 'wrap': (41, ''), 'death': (41, '')}
_CACHE = {}


def phx_frame(name, i, scale=3):
  """Returns (surface, anchor_x, anchor_y): the anchor is the bird's body centre inside the surface."""
  n, data = ANIMS[name]
  i = max(0, min(n - 1, int(i))) if name == 'death' else int(i) % n
  k = (name, i, scale)
  hit = _CACHE.get(k)
  if hit is None:
    raw = _CACHE.get((name, 'raw'))
    if raw is None:
      raw = _CACHE[(name, 'raw')] = zlib.decompress(base64.b64decode(data))
    m = W * H * 4
    s = pygame.image.frombuffer(raw[i * m:(i + 1) * m], (W, H), 'RGBA').copy()
    if scale != 1:
      s = pygame.transform.scale(s, (W * scale, H * scale))
    hit = _CACHE[k] = (s, AX * scale, AY * scale)
  return hit


def phx_frames(name):
  return ANIMS[name][0]
